(function(root){
  'use strict';
  const VERSION='reading-bank-2.6.3';
  const STORAGE_KEY='toeicReadingDrawsV263';
  const DATA={"part6":[{"id":"courier-delay","title":"Courier delay","text":"From: Northbank Dispatch\nTo: Ms. Alvarez\nSubject: Your equipment delivery\n\nA road closure has prevented our driver from reaching your office. We have {{1}} your delivery for Wednesday between 9 and 11 a.m. The items are being kept in our secure warehouse, and you will not be charged for the extra storage.\n\nPlease confirm that someone will be {{2}} to sign for the shipment during that period. {{3}} you require the equipment earlier, we can arrange collection from our depot on Tuesday afternoon. {{4}} We apologize for the disruption and appreciate your patience.","gaps":[{"options":["rescheduled","rescheduling","reschedule","reschedules"],"answer":0,"skill":"Verb form","explain":"Have must be followed by the past participle rescheduled."},{"options":["available","availability","availably","avail"],"answer":0,"skill":"Word form","explain":"The adjective available describes the person who can sign."},{"options":["If","Despite","Unless","During"],"answer":0,"skill":"Condition","explain":"If introduces the condition that makes early collection useful; unless would reverse the meaning."},{"options":["Please call us first so that we can prepare your order for collection.","Our depot does not permit customers to collect any orders.","All items were delivered to your office yesterday.","The extra storage charge will appear on your next invoice."],"answer":0,"skill":"Sentence completion","explain":"Calling before collection follows the alternative offered; the other sentences contradict the message."}]},{"id":"museum-volunteers","title":"Museum volunteer orientation","text":"VOLUNTEER NOTICE\n\nThe Hillcrest Museum is seeking volunteers for its weekend science exhibition. No previous museum experience is {{1}}, but applicants should enjoy speaking with visitors. Volunteers will help guests find demonstration rooms rather than operate the equipment.\n\nEveryone who is accepted must attend an orientation session. The session includes a {{2}} tour of the building and a short safety briefing. {{3}}, each volunteer will receive a list of frequently asked questions. {{4}} Applications close on 8 May; please use the form on the museum website.","gaps":[{"options":["required","requiring","requirement","requires"],"answer":0,"skill":"Passive voice","explain":"Is required is the passive form meaning that experience is necessary; no makes the requirement negative."},{"options":["guided","guidance","guiding","guidebook"],"answer":0,"skill":"Collocation","explain":"A guided tour is a tour led by someone; the other choices do not fit this noun phrase."},{"options":["In addition","Instead","Nevertheless","Otherwise"],"answer":0,"skill":"Addition","explain":"The question list is another benefit, not a replacement for the tour or briefing."},{"options":["This preparation will help volunteers respond confidently to visitors.","Experienced volunteers are excused from all orientation activities.","Visitors must operate every piece of equipment themselves.","The exhibition will be closed throughout every weekend."],"answer":0,"skill":"Sentence completion","explain":"The preparation refers to the orientation and question list, and explains their purpose."}]},{"id":"cafe-packaging","title":"Café packaging trial","text":"To our lunchtime customers:\n\nStarting on Monday, Linden Café will serve takeaway salads in reusable containers. Customers will pay a small deposit, which is refunded when the container is {{1}}. The trial will run for six weeks at our station branch only.\n\nWe have chosen containers that are {{2}} enough to be used many times. They must be returned to the café, not placed in a public recycling bin. {{3}} the trial ends, we will review return rates before deciding whether to introduce the system at other branches. {{4}} Thank you for helping us reduce packaging waste.","gaps":[{"options":["returned","returning","return","returns"],"answer":0,"skill":"Passive voice","explain":"The container receives the action, so is returned is needed."},{"options":["durable","durability","durably","duration"],"answer":0,"skill":"Adjective","explain":"Durable means able to withstand repeated use and fits before enough."},{"options":["After","During","Despite","Because of"],"answer":0,"skill":"Time clause","explain":"After can introduce the clause the trial ends; the other choices here require a noun phrase."},{"options":["Your participation will give us the information needed for that decision.","The system is already compulsory at every one of our branches.","Containers placed in public bins will be collected by café staff.","Customers will receive no refund when they return a container."],"answer":0,"skill":"Sentence completion","explain":"Participation supplies the return-rate data used in the expansion decision."}]},{"id":"server-maintenance","title":"Server maintenance window","text":"INTERNAL IT BULLETIN\n\nThe document server will be unavailable from 7 to 9 p.m. on Friday while technicians install replacement drives. Please save any open files {{1}} the shutdown begins. Email and the telephone system will remain operational.\n\nWe expect the replacement drives to improve retrieval {{2}}. Staff who need documents on Friday evening should download copies in advance. {{3}}, access will be restored at 9 p.m. unless final checks reveal a problem. {{4}} Do not attempt to restart the server yourself.","gaps":[{"options":["before","during","despite","because of"],"answer":0,"skill":"Time clause","explain":"Before introduces the clause the shutdown begins."},{"options":["speed","speedily","speedy","speeds up"],"answer":0,"skill":"Noun","explain":"Retrieval speed is the noun phrase naming what the drives should improve."},{"options":["As planned","On the contrary","For example","By comparison"],"answer":0,"skill":"Discourse","explain":"As planned refers to the stated two-hour maintenance window; there is no contradiction or example here."},{"options":["Any delay will be announced through the staff email list.","All office telephones will also be disconnected that evening.","Staff should keep their documents open during the shutdown.","The server will be unavailable for the whole of Saturday."],"answer":0,"skill":"Sentence completion","explain":"A delay announcement logically follows the possibility of a problem during final checks."}]},{"id":"training-reimbursement","title":"Course reimbursement","text":"From: Professional Development Team\nSubject: Applying for course reimbursement\n\nEmployees may request reimbursement for an external course if it relates directly to their current work. Applications must be approved by a supervisor before the course {{1}}. Approval does not cover travel or accommodation expenses.\n\nAfter completing the course, submit your receipt together with a certificate of {{2}}. Incomplete claims will be returned for correction. {{3}}, reimbursement may take longer if either document is missing. {{4}} The finance team processes complete claims on the last working day of each month.","gaps":[{"options":["begins","begin","beginning","begun"],"answer":0,"skill":"Present time clause","explain":"The singular subject course takes begins; present tense is used in this future time clause."},{"options":["completion","complete","completely","completed"],"answer":0,"skill":"Noun","explain":"A certificate of completion is evidence that a course was finished."},{"options":["Consequently","Nevertheless","Similarly","Instead"],"answer":0,"skill":"Result","explain":"The possible delay is a consequence of returning incomplete claims."},{"options":["Please check that both attachments are included before sending your claim.","Travel costs will automatically be added to every approved claim.","You may apply for approval only after the course has finished.","A supervisor must attend the entire course with you."],"answer":0,"skill":"Sentence completion","explain":"Checking both attachments directly addresses the missing-document problem."}]},{"id":"library-reservations","title":"Library study rooms","text":"CAMPUS LIBRARY UPDATE\n\nFrom 1 October, study rooms on the second floor can be booked online. Each booking is limited {{1}} two hours so that more students can use the rooms. Group members may not make consecutive bookings to extend the same meeting.\n\nThe new system will display room availability {{2}}, allowing users to see cancellations as they happen. {{3}} a room is not occupied within fifteen minutes of its booked start time, the reservation will be released. {{4}} Please cancel promptly when your plans change.","gaps":[{"options":["to","at","from","with"],"answer":0,"skill":"Preposition","explain":"Limited to states the maximum amount allowed."},{"options":["instantly","instant","instance","instants"],"answer":0,"skill":"Adverb","explain":"Instantly modifies display and matches as they happen."},{"options":["If","Although","Until","So that"],"answer":0,"skill":"Condition","explain":"Failure to occupy the room is the condition for releasing the reservation."},{"options":["Another group will then be able to book that room.","The same group will automatically receive an extra two hours.","All future reservations will be cancelled for the rest of the day.","Students must collect paper forms before every online booking."],"answer":0,"skill":"Sentence completion","explain":"That room refers to the room released after a no-show."}]},{"id":"hotel-renovation","title":"Hotel entrance renovation","text":"Dear Guest,\n\nWork on the entrance of the Cedar Hotel will begin on 12 June. During the project, guests will enter through the garden gate on Willow Street. Signs will be placed along the pavement to make the temporary entrance easy {{1}}.\n\nThe reception desk will remain in its usual {{2}} inside the lobby. {{3}} the outside work may be noisy between 10 a.m. and 4 p.m., guest rooms at the rear of the building are expected to remain quiet. {{4}} Our staff will assist you with any room-change request, subject to availability.","gaps":[{"options":["to find","finding","finds","found"],"answer":0,"skill":"Infinitive","explain":"Easy to find uses adjective + to-infinitive."},{"options":["location","locate","locally","located"],"answer":0,"skill":"Noun","explain":"Usual modifies the noun location."},{"options":["Although","Because of","Despite","During"],"answer":0,"skill":"Concession","explain":"Although introduces a full clause and contrasts the noisy work with the quiet rear rooms."},{"options":["Please let reception know if noise is affecting your stay.","Reception will move to the garden gate for the entire summer.","All rooms will be closed between 10 a.m. and 4 p.m.","Guests must carry their luggage without staff assistance."],"answer":0,"skill":"Sentence completion","explain":"A request to contact reception leads naturally to the offer of a room change."}]},{"id":"printer-warranty","title":"Printer warranty claim","text":"To: Service Department\nSubject: Printer model LX40\n\nWe purchased an LX40 printer from your company three months ago. It has recently started producing pages with faint vertical lines. Our technician replaced the toner, but this did not {{1}} the problem.\n\nThe warranty states that repairs are provided at no {{2}} during the first year. We have attached the purchase receipt and two sample pages. {{3}} you need further information, please contact our office administrator. {{4}} We would appreciate a reply before Friday because the printer is used for client reports.","gaps":[{"options":["resolve","resolved","resolving","resolves"],"answer":0,"skill":"Base verb","explain":"Did not is followed by the base form resolve."},{"options":["charge","charged","charging","charges"],"answer":0,"skill":"Collocation","explain":"At no charge means without a fee."},{"options":["Should","Despite","Since","Whether"],"answer":0,"skill":"Inverted condition","explain":"Should you need is the inverted form of if you should need."},{"options":["Please advise us on how to arrange a repair under the warranty.","We understand that our printer is already outside its one-year warranty.","The new toner has completely removed the lines from every page.","No sample pages are available for your technician to examine."],"answer":0,"skill":"Sentence completion","explain":"The request follows the evidence and warranty details and states the next action needed."}]},{"id":"market-vendors","title":"Weekend market registration","text":"RIVERSIDE MAKERS MARKET\n\nRegistration is now open for the autumn market. Spaces are available for vendors {{1}} sell handmade goods. Resale of factory-produced items is not permitted. Each space includes one table; vendors must bring their own display stands.\n\nApplications will be assessed according to product variety and the {{2}} of the submitted photographs. {{3}}, sending an application early does not guarantee acceptance. {{4}} Selected vendors will receive a confirmation email and payment instructions by 20 August.","gaps":[{"options":["who","whose","whom","which"],"answer":0,"skill":"Relative clause","explain":"Who is the subject of sell and refers to vendors."},{"options":["quality","qualify","qualified","qualitatively"],"answer":0,"skill":"Noun","explain":"The quality of the photographs is a noun phrase parallel to product variety."},{"options":["Therefore","For instance","Similarly","Meanwhile"],"answer":0,"skill":"Result","explain":"Assessment is based on products and photographs, so early submission alone cannot guarantee acceptance."},{"options":["The selection committee will review all submissions before allocating spaces.","Spaces are awarded automatically in the order applications arrive.","Only factory-produced items will be considered by the committee.","Vendors must pay the full fee before applying."],"answer":0,"skill":"Sentence completion","explain":"Reviewing all applications is consistent with the stated selection criteria."}]},{"id":"bike-storage","title":"Secure bicycle storage","text":"To: Building occupants\nFrom: Facilities Office\n\nA secure bicycle room will open beside the west entrance next week. Access cards can be {{1}} from the security desk upon presentation of a staff badge. There is no fee for using the room.\n\nBicycles must be parked inside the marked spaces to keep the entrance clear. The number of spaces is {{2}}, so access does not guarantee that a space will always be free. {{3}}, cyclists should still bring their own locks. {{4}} Items left in walkways will be moved to the facilities office.","gaps":[{"options":["obtained","obtaining","obtain","obtains"],"answer":0,"skill":"Passive modal","explain":"Can be obtained is the passive form after the modal can."},{"options":["limited","limitation","limit","limits"],"answer":0,"skill":"Adjective","explain":"Limited describes the finite number of spaces."},{"options":["In addition","Instead","As a result of","Even though"],"answer":0,"skill":"Addition","explain":"Bringing a lock is an additional instruction, not an alternative to parking in marked spaces."},{"options":["Please do not leave helmets or bags on the floor between spaces.","All bicycles must be stored across the entrance to the room.","Locks will be supplied free of charge to every cyclist.","Access cards can only be used after a monthly fee is paid."],"answer":0,"skill":"Sentence completion","explain":"The instruction about keeping the floor clear prepares for the warning about items in walkways."}]},{"id":"supplier-samples","title":"Supplier sample request","text":"Dear Ms. Iqbal,\n\nThank you for sending your catalogue of recycled fabrics. Before we place a bulk order, we would like to {{1}} the texture and colour of three materials in person. The product codes are listed in the attached spreadsheet.\n\nPlease send sample pieces large enough for our design team to assess them {{2}}. {{3}} there is a charge for the samples, let us know the total before dispatching them. {{4}} Our purchasing manager will contact you after the team has completed its evaluation.","gaps":[{"options":["examine","examined","examining","examines"],"answer":0,"skill":"Infinitive","explain":"Would like to is followed by the base verb examine."},{"options":["accurately","accurate","accuracy","accurateness"],"answer":0,"skill":"Adverb","explain":"Accurately modifies assess."},{"options":["If","Unless","Until","Despite"],"answer":0,"skill":"Condition","explain":"If introduces the possible existence of a sample charge."},{"options":["Please use the delivery address shown at the bottom of the spreadsheet.","We have already approved a bulk order for every fabric in your catalogue.","Small pictures will be sufficient instead of physical sample pieces.","Our evaluation was completed before your catalogue arrived."],"answer":0,"skill":"Sentence completion","explain":"Delivery instructions follow the request for physical samples and precede evaluation."}]},{"id":"bus-detour","title":"Bus route detour","text":"PASSENGER ANNOUNCEMENT\n\nBridge inspections will require Route 18 buses to use a temporary detour on Saturday. The stops at Park Lane and Mill Road will not be {{1}} between 8 a.m. and 5 p.m. Passengers should use the temporary stop outside the sports centre.\n\nJourney times may be {{2}} than usual because the detour includes two additional traffic lights. {{3}}, passengers connecting to regional trains should allow extra time. {{4}} Normal service is expected to resume when the inspections finish.","gaps":[{"options":["served","serving","service","serves"],"answer":0,"skill":"Passive voice","explain":"Stops are served by buses; will not be served is the passive construction."},{"options":["longer","long","longest","length"],"answer":0,"skill":"Comparison","explain":"Than requires the comparative longer."},{"options":["Consequently","Nevertheless","In contrast","For example"],"answer":0,"skill":"Result","explain":"Allowing extra time is a response to potentially longer journeys."},{"options":["Staff at the temporary stop will help passengers identify the correct bus.","The two closed stops will remain open throughout the inspections.","All regional trains have been cancelled for the entire weekend.","Passengers should expect journeys to be shorter than usual."],"answer":0,"skill":"Sentence completion","explain":"Assistance at the stated temporary stop is consistent with the detour arrangements."}]},{"id":"conference-speakers","title":"Conference speaker materials","text":"From: Program Coordinator\nTo: Conference Speakers\n\nWe look forward to welcoming you to the Small Business Forum. To help our technical team prepare, please send your presentation slides {{1}} 3 September. Use the session number as the file name.\n\nA technician will be available before each session to check that the slides display {{2}}. {{3}} your presentation includes sound, mention this in your email so that suitable equipment can be reserved. {{4}} A printed copy of the final program will be waiting at the registration desk.","gaps":[{"options":["by","among","along","throughout"],"answer":0,"skill":"Deadline","explain":"By indicates the latest acceptable submission date."},{"options":["correctly","correct","correction","correctness"],"answer":0,"skill":"Adverb","explain":"Correctly describes how the slides display."},{"options":["If","Despite","During","So as to"],"answer":0,"skill":"Condition","explain":"If introduces the condition that requires audio equipment."},{"options":["We cannot guarantee audio equipment for requests made on the day.","All presentations must be delivered without slides or sound.","There will be no technical support at any session.","Session numbers should never appear in presentation file names."],"answer":0,"skill":"Sentence completion","explain":"The warning explains why advance notice of audio requirements matters."}]},{"id":"bakery-vacancy","title":"Bakery apprenticeship","text":"APPRENTICE BAKER WANTED\n\nBrookfield Bakery is looking for an apprentice to join its morning team. The successful applicant will learn to prepare dough, shape loaves and {{1}} the ovens safely. Shifts begin at 5 a.m., so reliable early-morning transport is essential.\n\nApplicants should have a genuine {{2}} in food production. Previous baking experience is welcome but not necessary. {{3}}, all new apprentices receive training from a senior baker. {{4}} Please send a brief letter explaining why the role interests you.","gaps":[{"options":["operate","operated","operating","operates"],"answer":0,"skill":"Parallel verbs","explain":"Operate is parallel to prepare and shape after learn to."},{"options":["interest","interested","interesting","interestingly"],"answer":0,"skill":"Noun","explain":"A genuine interest in is the required noun phrase."},{"options":["In fact","On the contrary","Otherwise","By contrast"],"answer":0,"skill":"Explanation","explain":"In fact adds information supporting the statement that previous experience is unnecessary."},{"options":["The training will include both practical skills and food-safety procedures.","Only applicants who have managed a bakery may apply.","The position involves evening shifts beginning at 5 p.m.","Apprentices must learn to use the ovens without any supervision."],"answer":0,"skill":"Sentence completion","explain":"The training detail develops the offer of instruction from a senior baker."}]},{"id":"consultation-hours","title":"Design consultation hours","text":"NOTICE TO CLIENTS\n\nOur design studio is introducing online consultations for clients who cannot visit in person. Appointments can be made through the booking page, where available times are {{1}} each morning. You will receive a meeting link after your booking is confirmed.\n\nTo make the consultation as {{2}} as possible, please upload room photographs beforehand. {{3}} the connection fails during the meeting, your designer will call the telephone number provided on your form. {{4}} Online and in-person consultations are charged at the same rate.","gaps":[{"options":["updated","updating","update","updates"],"answer":0,"skill":"Passive voice","explain":"Available times are updated; the times receive the action."},{"options":["productive","productively","productivity","production"],"answer":0,"skill":"Adjective","explain":"As productive as possible describes the consultation."},{"options":["If","Although","Despite","Because of"],"answer":0,"skill":"Condition","explain":"If introduces the connection failure that triggers a phone call."},{"options":["Please check that this number is correct before submitting the form.","No telephone number is needed when booking an online consultation.","Room photographs may be uploaded only after the consultation ends.","Every online appointment costs more than an in-person meeting."],"answer":0,"skill":"Sentence completion","explain":"This number refers to the telephone number needed as a backup."}]},{"id":"warehouse-audit","title":"Warehouse safety audit","text":"To: Warehouse supervisors\nSubject: Preparation for the annual safety audit\n\nThe safety inspector will visit our warehouse on Thursday. Please ensure that all emergency exits remain {{1}} and that equipment inspection labels are visible. Do not move equipment simply to conceal a fault.\n\nAny unresolved problem should be recorded {{2}} in the audit log. {{3}} repairs have already been requested, the problem must stay on the list until a technician confirms that it has been fixed. {{4}} The inspector will use the log to prioritize areas needing attention.","gaps":[{"options":["accessible","access","accessibility","accessibly"],"answer":0,"skill":"Adjective","explain":"Remain is followed by the adjective accessible."},{"options":["clearly","clear","clearness","cleared"],"answer":0,"skill":"Adverb","explain":"Clearly modifies recorded."},{"options":["Even if","Because of","Despite","In addition to"],"answer":0,"skill":"Concession","explain":"Even if introduces the full clause and indicates that a repair request does not remove the reporting requirement."},{"options":["Include the location of each problem and the date it was first reported.","Delete all problems as soon as a repair request has been sent.","Only equipment that looks new needs an inspection label.","Close the emergency exits while the inspector is in the building."],"answer":0,"skill":"Sentence completion","explain":"Locations and report dates make the audit log useful for prioritizing attention."}]},{"id":"flower-subscription","title":"Flower subscription changes","text":"Dear Subscriber,\n\nWe are adding a seasonal arrangement to our weekly flower service. Existing subscribers will continue to receive their usual selection unless they {{1}} to the new option. Both options include delivery and a care-information card.\n\nThe seasonal arrangement uses flowers grown {{2}}, which may vary according to weather conditions. {{3}}, the precise colours cannot be guaranteed every week. {{4}} Changes requested by noon on Tuesday will take effect with Friday's delivery.","gaps":[{"options":["switch","switches","switching","switched"],"answer":0,"skill":"Present condition","explain":"They requires switch; a present-tense clause follows unless here."},{"options":["locally","local","locality","localize"],"answer":0,"skill":"Adverb","explain":"Locally modifies grown."},{"options":["For this reason","Nevertheless","On the other hand","For example"],"answer":0,"skill":"Result","explain":"Variation in available flowers explains why exact colours cannot be guaranteed."},{"options":["To select the seasonal option, update the preference in your account.","Every subscriber has already been moved to the seasonal option.","The colours are identical in every arrangement throughout the year.","Delivery charges are excluded from both subscription options."],"answer":0,"skill":"Sentence completion","explain":"The account instruction explains how to request the voluntary change."}]},{"id":"customer-return","title":"Returning a damaged chair","text":"Dear Mr. Bennett,\n\nWe are sorry that the chair arrived with a damaged leg. A replacement has been reserved for you and will be shipped once the original chair has been {{1}} by our courier. You do not need to take it to a store.\n\nPlease use the original packaging if it is still in good {{2}}. {{3}}, let us know so that the courier can bring suitable packing materials. {{4}} There will be no collection or replacement-delivery charge.","gaps":[{"options":["collected","collecting","collection","collects"],"answer":0,"skill":"Perfect passive","explain":"Has been collected forms the present perfect passive."},{"options":["condition","conditional","conditionally","conditioning"],"answer":0,"skill":"Collocation","explain":"In good condition means undamaged or usable."},{"options":["Otherwise","Similarly","In addition","Despite this"],"answer":0,"skill":"Alternative condition","explain":"Otherwise refers to the case in which the original packaging is not in good condition."},{"options":["Our courier will contact you to agree on a collection time.","Please return the chair to the store without contacting the courier.","The replacement cannot be reserved until you pay a new delivery fee.","You must buy packing materials even if the courier offers them."],"answer":0,"skill":"Sentence completion","explain":"Arranging a collection time is the next step in the offered courier return."}]},{"id":"office-art","title":"Office art display","text":"STAFF CULTURE COMMITTEE\n\nThe lobby display for November will feature photographs taken by employees. Each employee may submit up to two images, provided that permission has been {{1}} from any people clearly identifiable in them. Images should not include confidential business information.\n\nThe committee is looking for photographs that show a {{2}} perspective on everyday working life. {{3}} printing costs are covered by the company, there is no entry fee. {{4}} Please submit digital files rather than framed prints.","gaps":[{"options":["obtained","obtaining","obtain","obtains"],"answer":0,"skill":"Perfect passive","explain":"Has been obtained means that permission has already been secured."},{"options":["fresh","freshly","freshness","freshen"],"answer":0,"skill":"Adjective","explain":"Fresh modifies perspective and means new or original here."},{"options":["Because","Despite","During","Because of"],"answer":0,"skill":"Reason clause","explain":"Because introduces the clause printing costs are covered; because of would need a noun phrase."},{"options":["Selected images will be printed and mounted by the committee.","Employees must pay all printing costs before submitting their work.","Only photographs containing confidential information will be accepted.","All submissions must arrive in expensive wooden frames."],"answer":0,"skill":"Sentence completion","explain":"Committee printing explains why digital files, not framed prints, are requested."}]},{"id":"store-pickup","title":"Store pickup instructions","text":"ORDER COLLECTION NOTICE\n\nYour online order is ready to collect from our Eastgate shop. It will be held for seven days, after which uncollected items will be returned to stock and your payment {{1}}. Bring your order number and a form of identification.\n\nA friend may collect the order on your behalf if you provide written {{2}}. {{3}}, that person must show their own identification at the counter. {{4}} Please do not share your account password with anyone collecting an order for you.","gaps":[{"options":["refunded","refunding","refunds","refund"],"answer":0,"skill":"Parallel passive","explain":"Will be is shared: items will be returned and payment will be refunded."},{"options":["authorization","authorize","authorized","authorizing"],"answer":0,"skill":"Noun","explain":"Written authorization is permission given in writing."},{"options":["In addition","Instead","Otherwise","By contrast"],"answer":0,"skill":"Addition","explain":"Showing identification is required as well as written authorization."},{"options":["Give the collector your order number and a copy of your signed permission.","The collector must know your account password to receive the items.","Identification is not required when a friend collects the order.","Uncollected orders will remain at the shop indefinitely."],"answer":0,"skill":"Sentence completion","explain":"This gives the collector the booking details without sharing an account password; their own identification is still required."}]}],"part7":[{"id":"freight-collection","title":"Freight collection change","text":"EMAIL\nFrom: Harbor Freight Desk\nTo: Daniel Cho\nSubject: Collection of order 418\n\nYour display panels are ready at our waterfront depot. You requested collection on Thursday morning, but resurfacing work will close the loading entrance until noon. Collection is now available between 1 and 4 p.m. that day. Please reply by Wednesday to confirm a time within that period. If none of those times is suitable, we can hold the panels until Friday at no extra charge.\n\nThe panels are too wide for an ordinary passenger car. Please bring a van and show order number 418 at the gate. A member of our team will help load the panels; customers do not need to bring lifting equipment.","questions":[{"q":"Why has the collection time changed?","options":["The loading entrance will be closed in the morning.","The panels have not yet been manufactured.","The customer requested an extra panel.","The depot is moving to another district."],"answer":0,"evidence":"resurfacing work will close the loading entrance until noon","explain":"The entrance closure prevents collection on Thursday morning.","skill":"Detail"},{"q":"What should Mr. Cho do by Wednesday?","options":["Confirm an afternoon collection time.","Pay an additional storage fee.","Collect the panels before noon.","Send a photograph of his car."],"answer":0,"evidence":"Please reply by Wednesday to confirm a time within that period.","explain":"The requested reply is to confirm a time between 1 and 4 p.m.","skill":"Detail"},{"q":"What is offered if Thursday afternoon is unsuitable?","options":["Free storage until Friday.","A free delivery to his office.","A smaller set of panels.","Access to the depot at midnight."],"answer":0,"evidence":"we can hold the panels until Friday at no extra charge","explain":"The depot offers to hold the order for another day without a fee.","skill":"Detail"},{"q":"Why does the message recommend a van?","options":["The panels will not fit in a normal passenger car.","Vans are the only vehicles permitted after 4 p.m.","The depot will lend him a van free of charge.","The order includes lifting equipment."],"answer":0,"evidence":"The panels are too wide for an ordinary passenger car.","explain":"The size of the panels explains the recommendation.","skill":"Detail"},{"q":"What assistance is available at the depot?","options":["Help loading the panels.","Installation of the panels at an office.","Repairs to customers' vehicles.","Preparation of new display designs."],"answer":0,"evidence":"A member of our team will help load the panels","explain":"The team offers loading assistance, not installation or transport.","skill":"Detail"}]},{"id":"swim-registration","title":"Swimming course registration","text":"COMMUNITY CENTRE NOTICE\n\nAdult beginner swimming courses run for six consecutive Tuesdays, starting on 4 February. The morning class is from 10 to 11 a.m.; the evening class is from 7 to 8 p.m. Each course costs $90, including pool admission during lessons. Members receive a $10 reduction.\n\nRegister at reception and select one time slot for the whole course. Switching between morning and evening sessions is not permitted because each group progresses at its own pace. A maximum of eight people can join each class. If your preferred class is full, reception can add you to a waiting list.\n\nPlease bring a towel and swimwear. Goggles may be purchased at reception but are not required. Missed lessons cannot be carried forward to another course.","questions":[{"q":"How much does a centre member pay for the course?","options":["$80","$90","$100","$10"],"answer":0,"evidence":"Each course costs $90, including pool admission during lessons. Members receive a $10 reduction.","explain":"The member price is $90 minus $10, or $80.","skill":"Calculation"},{"q":"Why must participants keep the same time slot?","options":["The groups may progress at different speeds.","Evening lessons have a higher admission fee.","The pool closes permanently after 11 a.m.","The instructors cannot teach beginners."],"answer":0,"evidence":"each group progresses at its own pace","explain":"Different group progress is the stated reason for not switching.","skill":"Detail"},{"q":"What happens when a preferred class is full?","options":["A person may join a waiting list.","An additional lesson is guaranteed.","The course fee is doubled.","Morning members are moved automatically."],"answer":0,"evidence":"reception can add you to a waiting list","explain":"The notice offers a waiting list, not a guaranteed place.","skill":"Detail"},{"q":"Which item is optional?","options":["Goggles","Swimwear","A towel","A selected time slot"],"answer":0,"evidence":"Goggles may be purchased at reception but are not required.","explain":"Goggles are explicitly not required.","skill":"Detail"},{"q":"What does the notice say about missed lessons?","options":["They cannot be transferred to a later course.","They can be exchanged for pool equipment.","They are always refunded in full.","They may be attended in the other daily time slot."],"answer":0,"evidence":"Missed lessons cannot be carried forward to another course.","explain":"Carried forward means transferred for use later.","skill":"Policy"}]},{"id":"software-invoice","title":"Invoice correction","text":"EMAIL 1\nFrom: Maya Singh, Accounts\nTo: Brightpath Software\nSubject: Invoice B-219\n\nOur renewal agreement covers 12 user licences, but invoice B-219 charges us for 15. Three temporary licences were cancelled at the end of last month. Please issue a corrected invoice so that we can arrange payment before the 18 April deadline.\n\nEMAIL 2\nFrom: Brightpath Software\nTo: Maya Singh\n\nThank you for pointing this out. We have confirmed the cancellations and attached a replacement invoice for 12 licences. Please discard B-219 and quote B-224 when making payment. The original payment deadline is unchanged. Your access will continue without interruption while this correction is processed.","questions":[{"q":"What problem does Ms. Singh report?","options":["She was charged for too many licences.","All user accounts have stopped working.","The renewal agreement has expired.","The supplier used an incorrect office address."],"answer":0,"evidence":"Our renewal agreement covers 12 user licences, but invoice B-219 charges us for 15.","explain":"The number billed exceeds the agreed number.","skill":"Detail"},{"q":"How many licences had been cancelled?","options":["Three","Twelve","Fifteen","Eighteen"],"answer":0,"evidence":"Three temporary licences were cancelled at the end of last month.","explain":"The first email identifies three cancelled temporary licences.","skill":"Detail"},{"q":"Which reference should be used for payment?","options":["B-224","B-219","18 April","12-15"],"answer":0,"evidence":"quote B-224 when making payment","explain":"The replacement invoice has reference B-224.","skill":"Detail"},{"q":"When is payment still due?","options":["18 April","At the end of next month","Immediately upon cancellation","A date that will be announced later"],"answer":0,"evidence":"The original payment deadline is unchanged.","explain":"The first email gives 18 April; the reply keeps that deadline.","skill":"Cross-reference"},{"q":"What can be concluded about the correction?","options":["It will not interrupt software access.","It will add three new temporary accounts.","It requires the customer to sign a new agreement.","It removes the need to pay for the remaining licences."],"answer":0,"evidence":"Your access will continue without interruption while this correction is processed.","explain":"The supplier expressly assures continued access.","skill":"Inference"}]},{"id":"garden-workshop","title":"Garden workshop venue","text":"WORKSHOP ANNOUNCEMENT\n\nThe Urban Garden Club's composting workshop on Saturday 16 March will now take place in the East Hall, not in the community garden. Heavy rain is forecast, and several demonstrations require a dry working area. The starting time remains 2 p.m.\n\nThe instructor will demonstrate two small-scale composting methods suitable for apartment balconies. Participants will then assemble a starter container to take home. Containers and compost materials are included in the $25 fee, but participants should bring gardening gloves.\n\nThe East Hall has no on-site parking. The nearest public car park is on Birch Street, a five-minute walk away. Anyone who cannot attend at the new venue may request a refund by emailing the club before noon on Friday.","questions":[{"q":"Why has the workshop been moved?","options":["Rain would interfere with the demonstrations.","The original venue charged a higher fee.","The club expects twice as many participants.","The instructor needs a larger outdoor garden."],"answer":0,"evidence":"Heavy rain is forecast, and several demonstrations require a dry working area.","explain":"The weather and dry-area requirement caused the move.","skill":"Detail"},{"q":"What has not changed?","options":["The 2 p.m. starting time.","The location in the community garden.","The requirement to bring a container.","The availability of parking at the venue."],"answer":0,"evidence":"The starting time remains 2 p.m.","explain":"The announcement explicitly preserves the starting time.","skill":"Detail"},{"q":"What will participants make?","options":["A composting starter container.","A wooden balcony bench.","A pair of gardening gloves.","An outdoor rain shelter."],"answer":0,"evidence":"Participants will then assemble a starter container to take home.","explain":"The activity is assembling a starter container.","skill":"Detail"},{"q":"What should participants provide themselves?","options":["Gardening gloves","Compost materials","Starter containers","Demonstration tables"],"answer":0,"evidence":"participants should bring gardening gloves","explain":"Materials and containers are included, but gloves are not.","skill":"Detail"},{"q":"What is the deadline for requesting a refund?","options":["Before noon on Friday.","By 2 p.m. on Saturday.","Within five days after the workshop.","At the end of March."],"answer":0,"evidence":"before noon on Friday","explain":"Refund requests must arrive before Friday noon.","skill":"Detail"}]},{"id":"catering-change","title":"Catering numbers and choices","text":"ORDER CONFIRMATION\nSeabrook Catering — Order C47\nEvent: Team lunch, 22 May\nDelivery: 12:15 p.m., reception desk\nOrder: 18 chicken lunches, 6 vegetarian lunches\nChanges to quantities accepted until 3 p.m. two working days before the event. Please quote the order number in all messages.\n\nEMAIL\nTo: Seabrook Catering\nSubject: C47 amendment\n\nTwo colleagues have joined our lunch, and both require vegetarian meals. Please add them to our order without changing the chicken lunches. We will also be meeting in the fourth-floor lounge rather than reception. Please ask the driver to call me on arrival so I can meet them downstairs. We still need the food at the confirmed time.","questions":[{"q":"How many lunches were originally ordered?","options":["24","18","6","26"],"answer":0,"evidence":"Order: 18 chicken lunches, 6 vegetarian lunches","explain":"Eighteen plus six equals twenty-four.","skill":"Calculation"},{"q":"What quantity of vegetarian lunches is requested after the change?","options":["8","6","18","20"],"answer":0,"evidence":"Two colleagues have joined our lunch, and both require vegetarian meals.","explain":"The original six vegetarian lunches increase by two.","skill":"Cross-reference"},{"q":"Which part of the food order remains unchanged?","options":["The 18 chicken lunches.","The total number of lunches.","The number of vegetarian lunches.","The absence of dietary requests."],"answer":0,"evidence":"without changing the chicken lunches","explain":"The amendment keeps the original chicken quantity.","skill":"Detail"},{"q":"What should the driver do upon arrival?","options":["Call the person who sent the email.","Go directly to the fourth floor unaccompanied.","Leave all the food outside the building.","Return to the caterer for a new order number."],"answer":0,"evidence":"Please ask the driver to call me on arrival","explain":"The sender will meet the driver downstairs after the call.","skill":"Detail"},{"q":"What delivery time applies after the amendment?","options":["12:15 p.m.","3 p.m.","4 p.m.","A new time still to be agreed"],"answer":0,"evidence":"We still need the food at the confirmed time.","explain":"The confirmed time in the first document is 12:15 p.m.","skill":"Cross-reference"}]},{"id":"job-interview","title":"Interview preparation","text":"From: Coastal Research Recruitment\nTo: Elena Perez\nSubject: Interview arrangements\n\nThank you for your application for the laboratory assistant position. We would like to invite you to an interview on 9 July at 10:30 a.m. Please arrive fifteen minutes early to collect a visitor badge at reception. The interview will last approximately forty minutes.\n\nYou do not need to prepare a presentation. Instead, please bring an example of a record-keeping task you have completed, with any confidential information removed. The panel will ask you to explain how you checked its accuracy.\n\nOur building is a ten-minute walk from Central Station. We can reimburse standard train fares if you retain your ticket. Taxi fares and parking charges are not covered. Please confirm your attendance by replying to this message by 2 July.","questions":[{"q":"What time should Ms. Perez arrive at reception?","options":["10:15 a.m.","10:30 a.m.","10:45 a.m.","11:10 a.m."],"answer":0,"evidence":"an interview on 9 July at 10:30 a.m. Please arrive fifteen minutes early","explain":"Fifteen minutes before 10:30 is 10:15.","skill":"Calculation"},{"q":"What should she bring to the interview?","options":["A nonconfidential example of her record-keeping work.","A prepared slide presentation.","A complete set of confidential laboratory records.","A reference letter from a train operator."],"answer":0,"evidence":"bring an example of a record-keeping task you have completed, with any confidential information removed","explain":"A work example is requested, with confidential details removed.","skill":"Detail"},{"q":"What aspect of the example will the panel discuss?","options":["How its accuracy was checked.","How much the paper cost.","Who designed its original logo.","Why a taxi was used to deliver it."],"answer":0,"evidence":"The panel will ask you to explain how you checked its accuracy.","explain":"Accuracy checking is the stated discussion topic.","skill":"Detail"},{"q":"Which expense may be reimbursed?","options":["A standard train fare.","A taxi fare.","A parking charge.","The cost of a visitor badge."],"answer":0,"evidence":"We can reimburse standard train fares if you retain your ticket.","explain":"Only a standard train fare with a retained ticket is covered.","skill":"Detail"},{"q":"What response is requested by 2 July?","options":["Confirmation that she will attend.","Submission of a new job application.","Payment of an interview fee.","The results of a laboratory experiment."],"answer":0,"evidence":"Please confirm your attendance by replying to this message by 2 July.","explain":"The required response is attendance confirmation.","skill":"Detail"}]},{"id":"equipment-booking","title":"Equipment loan rules","text":"STAFF EQUIPMENT LIBRARY\n\nPortable projectors, cameras and audio recorders are available for work-related projects. Reserve equipment through the staff portal at least one working day before collection. Items can be collected from the media office between 9 a.m. and noon.\n\nLoans normally last three days. An extension may be approved only if no other reservation overlaps with the requested period. Please ask for an extension before the original return date; keeping equipment without approval may result in a temporary loss of borrowing privileges.\n\nCheck all accessories against the inventory list when you collect an item. Report anything missing immediately so that the loan record can be corrected. A fault discovered during use should be reported to the media office, not repaired by the borrower.","questions":[{"q":"When should an equipment reservation be made?","options":["At least one working day before collection.","Only after collecting the item.","Exactly three weeks in advance.","Whenever the equipment is returned."],"answer":0,"evidence":"at least one working day before collection","explain":"The portal reservation needs at least one working day of notice.","skill":"Detail"},{"q":"Under what condition can a loan be extended?","options":["No other reservation conflicts with the extension.","The borrower has already kept the item past its return date.","The borrower agrees to repair the item.","The equipment has no accessories."],"answer":0,"evidence":"only if no other reservation overlaps with the requested period","explain":"No overlapping reservation is the condition for approval.","skill":"Detail"},{"q":"What may happen after an unauthorized late return?","options":["Borrowing privileges may be suspended temporarily.","All staff reservations will be cancelled.","The borrower automatically becomes the equipment owner.","The standard loan period will change to a week."],"answer":0,"evidence":"a temporary loss of borrowing privileges","explain":"The possible penalty is a temporary borrowing restriction.","skill":"Detail"},{"q":"Why should missing accessories be reported at collection?","options":["So the loan record can be corrected.","So the borrower can be charged for a longer loan.","So all projectors can be withdrawn from use.","So a new staff portal password can be issued."],"answer":0,"evidence":"Report anything missing immediately so that the loan record can be corrected.","explain":"An immediate report keeps the record accurate.","skill":"Detail"},{"q":"What should a borrower do if an item develops a fault?","options":["Notify the media office.","Attempt to repair it personally.","Keep it without requesting an extension.","Pass it to a colleague without reporting the fault."],"answer":0,"evidence":"A fault discovered during use should be reported to the media office, not repaired by the borrower.","explain":"Borrowers should report faults rather than repair equipment.","skill":"Detail"}]},{"id":"bakery-preorders","title":"Festival bread preorders","text":"BAKER'S NOTE\n\nFor the town's harvest festival, Stone Mill Bakery will produce a limited batch of walnut and raisin loaves. Each loaf costs $8. Orders must be placed in the shop by Thursday at 5 p.m.; payment is required when ordering. We cannot accept orders by social media message.\n\nCollection is available on Saturday between 8 a.m. and 1 p.m. Please bring your receipt. If someone else collects for you, give that person the receipt or a clear photograph of it. Uncollected loaves will be donated to the community kitchen after 1 p.m., and payments will not be refunded.\n\nThe festival loaves contain nuts, wheat and milk. Our usual nut-free bread will still be sold on Saturday, but it is made in the same kitchen and is not guaranteed to be free from traces of nuts.","questions":[{"q":"How must festival loaves be ordered?","options":["In person at the shop.","By social media message.","At the community kitchen.","Through the town council website."],"answer":0,"evidence":"Orders must be placed in the shop","explain":"The notice requires ordering in the shop.","skill":"Detail"},{"q":"When is payment due?","options":["When the order is placed.","After the festival has ended.","Only when someone else collects the bread.","Within one week of collection."],"answer":0,"evidence":"payment is required when ordering","explain":"Payment is due at the time of ordering.","skill":"Detail"},{"q":"What can another person use to collect an order?","options":["A clear photograph of the receipt.","Any photograph of the bakery.","A message from the town council.","A promise to pay next week."],"answer":0,"evidence":"give that person the receipt or a clear photograph of it","explain":"The receipt itself or a clear photo is accepted.","skill":"Detail"},{"q":"What happens to loaves not collected by 1 p.m. on Saturday?","options":["They are donated without a refund.","They are stored until the next festival.","They are delivered free to the purchaser.","They are exchanged for nut-free bread automatically."],"answer":0,"evidence":"Uncollected loaves will be donated to the community kitchen after 1 p.m., and payments will not be refunded.","explain":"Both donation and the absence of refunds are stated.","skill":"Detail"},{"q":"What caution is given about the usual nut-free bread?","options":["It may contain traces of nuts from the shared kitchen.","It will not be available on Saturday.","It costs twice the festival loaf price.","It contains walnut pieces as a main ingredient."],"answer":0,"evidence":"it is made in the same kitchen and is not guaranteed to be free from traces of nuts","explain":"Shared preparation space prevents a guarantee against traces.","skill":"Inference"}]},{"id":"travel-connection","title":"Shuttle and train connection","text":"HOTEL SHUTTLE TIMETABLE\nDepartures from hotel: 7:10 a.m. / 7:40 a.m. / 8:10 a.m.\nJourney to station: 20 minutes\nSeats must be reserved at reception by 9 p.m. on the previous evening. The shuttle is free for registered guests. The driver cannot wait for late passengers.\n\nGUEST MESSAGE\nTo: Reception\n\nI need to catch the 8:05 train tomorrow and would like at least fifteen minutes at the station to find my platform. Please reserve the latest shuttle that will allow this. I am staying in room 306 and have one small suitcase. Please confirm the departure time before this evening.","questions":[{"q":"By what time does the guest want to reach the station?","options":["7:50 a.m.","8:05 a.m.","8:10 a.m.","7:10 a.m."],"answer":0,"evidence":"catch the 8:05 train tomorrow and would like at least fifteen minutes at the station","explain":"Fifteen minutes before 8:05 is 7:50.","skill":"Calculation"},{"q":"Which shuttle meets the guest's request?","options":["The 7:10 a.m. shuttle.","The 7:40 a.m. shuttle.","The 8:10 a.m. shuttle.","Any of the listed departures."],"answer":0,"evidence":"Journey to station: 20 minutes","explain":"The 7:40 shuttle arrives at 8:00, too late for a fifteen-minute buffer; 7:10 is the latest feasible departure.","skill":"Cross-reference"},{"q":"What is required to secure a shuttle seat?","options":["A reservation at reception by the previous evening.","Payment directly to the train driver.","A request only after arriving at the station.","A printed list of all hotel guests."],"answer":0,"evidence":"Seats must be reserved at reception by 9 p.m. on the previous evening.","explain":"An advance reception reservation is required.","skill":"Detail"},{"q":"How much will the guest pay for the shuttle?","options":["Nothing.","The same fare as the train.","$15.","A fee based on suitcase weight."],"answer":0,"evidence":"The shuttle is free for registered guests.","explain":"The message identifies a hotel guest, for whom the shuttle is free.","skill":"Cross-reference"},{"q":"What must the guest avoid doing?","options":["Arriving late for the shuttle.","Bringing any suitcase.","Requesting a confirmation.","Finding a train platform early."],"answer":0,"evidence":"The driver cannot wait for late passengers.","explain":"The shuttle will not wait for late passengers.","skill":"Inference"}]},{"id":"recycling-audit","title":"Recycling audit findings","text":"OPERATIONS REPORT EXTRACT\n\nLast month's waste audit found that paper recycling bins in the north office contained many plastic food containers. Interviewed staff said the labels were difficult to read from a distance. The audit team recommends larger labels with examples of accepted items.\n\nThe south office had fewer sorting errors after moving its recycling bins beside the general waste bins. Staff could then compare the options before disposing of an item. The team recommends testing this arrangement in the north office for four weeks before purchasing additional bins.\n\nA second audit will measure the proportion of incorrectly sorted items, not simply the amount collected. Collecting more material would not represent an improvement if much of it could not be recycled.","questions":[{"q":"What issue was found in the north office?","options":["Plastic containers were placed in paper bins.","Paper bins were completely unused.","There were no general waste bins anywhere.","All labels had been removed deliberately."],"answer":0,"evidence":"paper recycling bins in the north office contained many plastic food containers","explain":"The contamination was plastic in paper recycling.","skill":"Detail"},{"q":"What explanation did staff give?","options":["The labels were hard to read at a distance.","The bins were locked all day.","The audit had been cancelled.","Plastic containers were listed as paper products."],"answer":0,"evidence":"the labels were difficult to read from a distance","explain":"Poor readability was the reported explanation.","skill":"Detail"},{"q":"What change helped the south office?","options":["Placing recycling and general waste bins together.","Removing every recycling bin.","Collecting waste only once a month.","Replacing paper labels with blank panels."],"answer":0,"evidence":"moving its recycling bins beside the general waste bins","explain":"Co-location helped staff compare disposal choices.","skill":"Detail"},{"q":"What should occur before extra bins are bought?","options":["A four-week trial in the north office.","Immediate closure of the south office.","A ban on all food containers.","A year without any waste collection."],"answer":0,"evidence":"testing this arrangement in the north office for four weeks before purchasing additional bins","explain":"A trial is recommended before purchasing more bins.","skill":"Detail"},{"q":"What will the next audit chiefly measure?","options":["The proportion of sorting mistakes.","The price of plastic containers.","The distance between the two offices.","Only the total volume collected."],"answer":0,"evidence":"the proportion of incorrectly sorted items, not simply the amount collected","explain":"The measure focuses on sorting accuracy rather than quantity.","skill":"Detail"}]},{"id":"bookstore-reading","title":"Author event admission","text":"BRAMBLE BOOKS — AUTHOR EVENING\n\nNovelist Amina Reed will discuss her new book, The Last Platform, on 14 November. Doors open at 6:15 p.m., and the conversation begins at 6:45. The event is free, but a reservation is essential because only forty seats are available.\n\nReserved seats will be held until 6:35 p.m. After that time, unclaimed seats may be offered to people on the waiting list. Guests arriving after the conversation starts will be admitted during a suitable pause.\n\nA book signing follows the conversation. Copies purchased from another shop may be signed, but no more than two books per person. Photography is allowed during the signing, not during the discussion. Please contact the shop before the event if you require step-free access; staff will arrange entry through the side door.","questions":[{"q":"Why is advance reservation necessary?","options":["There are only forty seats.","All guests must buy two books.","The event charges a high admission fee.","The author will sign books only before the event."],"answer":0,"evidence":"a reservation is essential because only forty seats are available","explain":"The limited seating explains the reservation requirement.","skill":"Detail"},{"q":"Until what time are reserved seats guaranteed to be held?","options":["6:35 p.m.","6:15 p.m.","6:45 p.m.","7:15 p.m."],"answer":0,"evidence":"Reserved seats will be held until 6:35 p.m.","explain":"Seats can be released after 6:35.","skill":"Detail"},{"q":"When may late arrivals enter?","options":["During a suitable pause in the conversation.","Only after the shop closes.","At any moment while the author is speaking.","Before doors open the next day."],"answer":0,"evidence":"Guests arriving after the conversation starts will be admitted during a suitable pause.","explain":"Late entry is delayed until a suitable pause.","skill":"Detail"},{"q":"What is permitted at the signing?","options":["Signing up to two books bought elsewhere.","Signing an unlimited number of books per person.","Photographing the discussion retrospectively.","Exchanging any book for a free event ticket."],"answer":0,"evidence":"Copies purchased from another shop may be signed, but no more than two books per person.","explain":"Outside purchases are accepted within the two-book limit.","skill":"Detail"},{"q":"Why should a guest request step-free access in advance?","options":["So staff can arrange entry through the side door.","So the guest can reserve all forty seats.","So photography permission can be removed.","So the author can arrive earlier."],"answer":0,"evidence":"staff will arrange entry through the side door","explain":"Advance contact allows staff to prepare the accessible entrance.","skill":"Detail"}]},{"id":"return-credit","title":"Return and replacement order","text":"CUSTOMER EMAIL\n\nI ordered six blue storage boxes, but two arrived in green. The packing list shows six blue boxes. I would like the incorrect boxes replaced. The other four are suitable and will be kept. I have attached a photograph of the delivery label and the two green boxes.\n\nSUPPLIER REPLY\n\nWe apologize for the packing error. Two blue boxes will be dispatched tomorrow. Please place the green boxes in the packaging used for the replacement and attach the prepaid return label enclosed with it. You can leave the parcel at any branch of our partner collection service within fourteen days. No new payment is required, and you do not need to return the four correct boxes.","questions":[{"q":"What was wrong with the delivered order?","options":["Two boxes were the wrong colour.","All six boxes were damaged.","The packing list requested green boxes.","Only two boxes were delivered."],"answer":0,"evidence":"two arrived in green. The packing list shows six blue boxes.","explain":"Two green boxes were delivered instead of blue ones.","skill":"Detail"},{"q":"How many boxes does the customer intend to keep from the original delivery?","options":["Four","Two","Six","Eight"],"answer":0,"evidence":"The other four are suitable and will be kept.","explain":"Four correct boxes are to be kept.","skill":"Detail"},{"q":"What will be enclosed with the replacements?","options":["A prepaid return label.","A new invoice requiring payment.","A form requesting return of all six boxes.","Six green storage boxes."],"answer":0,"evidence":"the prepaid return label enclosed with it","explain":"The replacements include a return label with postage paid.","skill":"Detail"},{"q":"How should the wrong boxes be packaged for return?","options":["In the packaging used for the replacements.","Without any protective packaging.","In a new wooden crate bought by the customer.","Together with all four correct boxes."],"answer":0,"evidence":"place the green boxes in the packaging used for the replacement","explain":"The supplier instructs reuse of the replacement packaging.","skill":"Detail"},{"q":"What must the customer do within fourteen days?","options":["Leave the return parcel at a partner collection branch.","Pay for the two replacement boxes.","Submit a new order for six green boxes.","Return the four correct boxes to the factory."],"answer":0,"evidence":"leave the parcel at any branch of our partner collection service within fourteen days","explain":"The deadline applies to handing over the return parcel.","skill":"Detail"}]},{"id":"mentoring-scheme","title":"Mentoring scheme pilot","text":"HUMAN RESOURCES UPDATE\n\nA six-month mentoring pilot will match recently promoted supervisors with experienced managers from another department. The aim is to provide a confidential space to discuss common management challenges, not to assess job performance.\n\nPairs should meet for at least forty-five minutes each month. Meetings can be held online or in person during working hours. Participants should agree on discussion topics in advance; mentors will not receive copies of their partners' performance reviews.\n\nParticipation is voluntary. Applications close on 30 January, and matches will be announced in February. If a match proves unsuitable, either participant may request a new partner without giving a detailed reason. At the end of the pilot, an anonymous survey will help HR decide whether to continue the scheme.","questions":[{"q":"Who is the pilot intended to support?","options":["Recently promoted supervisors.","Only employees about to retire.","External job applicants.","Customers making formal complaints."],"answer":0,"evidence":"recently promoted supervisors","explain":"The scheme pairs newly promoted supervisors with experienced managers.","skill":"Detail"},{"q":"What is not a purpose of the scheme?","options":["Assessing job performance.","Discussing management challenges.","Providing confidential support.","Connecting people from different departments."],"answer":0,"evidence":"not to assess job performance","explain":"Performance assessment is explicitly excluded.","skill":"Detail"},{"q":"What meeting commitment is expected?","options":["At least forty-five minutes each month.","Exactly six hours every week.","A daily meeting outside working hours.","One meeting only at the end of the pilot."],"answer":0,"evidence":"at least forty-five minutes each month","explain":"The minimum commitment is specified monthly.","skill":"Detail"},{"q":"What can a participant do if the pairing is unsuitable?","options":["Ask for a different partner without a detailed explanation.","Demand the other person's performance review.","Withdraw the other person's promotion.","Extend the pilot automatically by six months."],"answer":0,"evidence":"either participant may request a new partner without giving a detailed reason","explain":"A change of partner is allowed without a detailed reason.","skill":"Detail"},{"q":"How will HR assess whether to continue the scheme?","options":["Through an anonymous survey.","By publishing every discussion transcript.","By comparing customers' payment records.","By asking mentors to assign performance grades."],"answer":0,"evidence":"an anonymous survey will help HR decide whether to continue the scheme","explain":"The stated evaluation tool is an anonymous survey.","skill":"Detail"}]},{"id":"repair-estimate","title":"Bicycle repair estimate","text":"REPAIR ESTIMATE — HAWTHORN CYCLES\nJob R62\nReplacement chain: $24\nBrake adjustment: $18\nLabour for both tasks: $28\nTotal estimate: $70\nWork begins only after customer approval. If additional repairs are needed, staff will seek approval before exceeding the estimate.\n\nMESSAGE FROM TECHNICIAN\n\nWe inspected your bicycle this morning. The tyres are serviceable, so replacement is not necessary at present. The chain and brakes require the work listed above. If you approve by 2 p.m. today, collection should be possible after 4 p.m. tomorrow. Please note that the shop closes at 6 p.m. We will call if the completion time changes.","questions":[{"q":"What does the $70 estimate include?","options":["A chain, brake adjustment and labour.","Two new tyres and a new frame.","Labour only.","A replacement bicycle."],"answer":0,"evidence":"Replacement chain: $24\nBrake adjustment: $18\nLabour for both tasks: $28\nTotal estimate: $70","explain":"The three listed charges total $70.","skill":"Cross-reference"},{"q":"Why are new tyres not included?","options":["The existing tyres can still be used.","The customer has already supplied new tyres.","The shop is unable to work on tyres.","The technician forgot to inspect them."],"answer":0,"evidence":"The tyres are serviceable, so replacement is not necessary at present.","explain":"Serviceable means fit for use.","skill":"Vocabulary in context"},{"q":"What must happen before the repair work starts?","options":["The customer must approve it.","The shop must close for the day.","Every bicycle part must be replaced.","The customer must agree to unlimited charges."],"answer":0,"evidence":"Work begins only after customer approval.","explain":"Approval is required before work starts.","skill":"Detail"},{"q":"If approval is given in time and work proceeds as expected, when can the bicycle be collected?","options":["Tomorrow between 4 and 6 p.m.","Today before 2 p.m.","Tomorrow before 9 a.m.","Any time after midnight."],"answer":0,"evidence":"collection should be possible after 4 p.m. tomorrow. Please note that the shop closes at 6 p.m.","explain":"The completion estimate and closing time give the collection window.","skill":"Cross-reference"},{"q":"What will happen if extra repairs would exceed the estimate?","options":["Staff will ask for further approval.","The charge will automatically be doubled.","The bicycle will be sold without notice.","The original work will be free."],"answer":0,"evidence":"staff will seek approval before exceeding the estimate","explain":"Additional costs require approval rather than automatic billing.","skill":"Detail"}]},{"id":"restaurant-feedback","title":"Restaurant booking feedback","text":"To: Willow Table Restaurant\n\nOur group enjoyed dinner on Wednesday, particularly the vegetarian menu. However, I want to clarify one aspect of the booking process. Your website said parties of eight or more should select a set menu, so we chose one for our group of nine. On arrival, we learned that the rule applies only on Friday and Saturday evenings.\n\nWe were happy with the meal, but several guests would have preferred to order individual dishes. Could you make the days more prominent on the booking page? The confirmation email repeated the set-menu requirement without mentioning the exception, which reinforced our misunderstanding.\n\nI am not seeking a refund. I hope this feedback helps future guests choose correctly. Our server handled the situation politely and deserves our thanks.","questions":[{"q":"When did the group dine at the restaurant?","options":["Wednesday","Friday","Saturday","Sunday"],"answer":0,"evidence":"Our group enjoyed dinner on Wednesday","explain":"The writer specifies Wednesday.","skill":"Detail"},{"q":"What caused the booking misunderstanding?","options":["The day restriction was unclear in the online information.","The restaurant offered no vegetarian food.","The group contained fewer than eight people.","The server refused to read the confirmation."],"answer":0,"evidence":"the rule applies only on Friday and Saturday evenings","explain":"The group mistakenly believed the set-menu rule also applied on Wednesday.","skill":"Detail"},{"q":"What would some guests have preferred?","options":["Ordering individual dishes.","Moving dinner to a different restaurant.","Eating without making any reservation.","Cancelling all vegetarian meals."],"answer":0,"evidence":"several guests would have preferred to order individual dishes","explain":"The writer states a preference for individual menu choices.","skill":"Detail"},{"q":"What change does the writer request?","options":["Make the applicable days clearer on the booking page.","Remove all set menus permanently.","Dismiss the server who handled the booking.","Refund the entire bill immediately."],"answer":0,"evidence":"Could you make the days more prominent on the booking page?","explain":"The requested change concerns visibility of the day restriction.","skill":"Detail"},{"q":"How does the writer describe the server?","options":["Polite and deserving thanks.","Responsible for the misleading website.","Unable to explain any menu choice.","Unwilling to speak with the group."],"answer":0,"evidence":"Our server handled the situation politely and deserves our thanks.","explain":"The writer praises the server rather than blaming them.","skill":"Attitude"}]},{"id":"language-exchange","title":"Language exchange sessions","text":"LOCAL LEARNING HUB\n\nOur language exchange pairs speakers who want to practise each other's language. It is not a taught course: partners decide their own activities and divide each meeting equally between the two languages. Participants must be at least eighteen years old.\n\nNew members attend an introductory meeting on the first Thursday of the month at 6 p.m. Staff explain the guidelines and help people find compatible partners. A partner cannot be guaranteed for every language immediately; unmatched members can join a conversation table while waiting.\n\nMembership costs $12 per year and includes use of the meeting space on weekday evenings. Paid tutoring, sales promotions and recruitment are not allowed during exchange sessions. Members who need to cancel a meeting should contact their partner directly rather than ask the hub to pass on the message.","questions":[{"q":"How are exchange activities selected?","options":["The partners choose them.","A teacher assigns a compulsory textbook.","A recruitment agency sets all topics.","Only hub staff may suggest a topic."],"answer":0,"evidence":"partners decide their own activities","explain":"The exchange is participant-led, not a taught course.","skill":"Detail"},{"q":"How should meeting time be divided?","options":["Equally between the two languages.","Entirely in the language of the older partner.","According to how much each person paid.","Only after a formal examination."],"answer":0,"evidence":"divide each meeting equally between the two languages","explain":"Equal time is the stated guideline.","skill":"Detail"},{"q":"What can a member do while waiting for a partner?","options":["Join a conversation table.","Demand an immediate refund from a tutor.","Recruit employees during exchange sessions.","Skip the age requirement."],"answer":0,"evidence":"unmatched members can join a conversation table while waiting","explain":"A conversation table is the alternative while unmatched.","skill":"Detail"},{"q":"What does the annual membership include?","options":["Weekday-evening use of the meeting space.","Private tutoring every weekend.","A guaranteed partner for every language.","Permission to sell products during meetings."],"answer":0,"evidence":"includes use of the meeting space on weekday evenings","explain":"The fee includes the specified use of space.","skill":"Detail"},{"q":"Who should be contacted to cancel a meeting?","options":["The exchange partner directly.","The hub to relay the message.","A prospective employer.","Every person on the membership list."],"answer":0,"evidence":"contact their partner directly rather than ask the hub to pass on the message","explain":"The cancellation should be communicated directly.","skill":"Detail"}]},{"id":"photo-contest","title":"Photography contest rules","text":"CITY VIEWS PHOTOGRAPHY CONTEST\n\nWe invite photographs showing how public spaces are used in daily life. Images must have been taken within the city during the current calendar year. Each entrant may submit up to three images, but only one can receive a prize.\n\nBasic cropping and exposure correction are allowed. Removing people or adding objects digitally is not permitted. Entrants retain copyright, but winning images may be displayed on the city website and in a free public exhibition, with the photographer credited.\n\nSubmit image files through the contest portal by 10 October. Printed entries will not be accepted. Finalists will be contacted by email and asked to provide the original unedited files. The judges will consider relevance to the theme, composition and the clarity of the story conveyed.","questions":[{"q":"Which photograph meets the location and date rules?","options":["A city park photographed inside the city this year.","A rural scene outside the city from this year.","A city square photographed five years ago.","A digitally invented location with no original photograph."],"answer":0,"evidence":"Images must have been taken within the city during the current calendar year.","explain":"Both location and current-year requirements must be met.","skill":"Detail"},{"q":"Which edit is permitted?","options":["Cropping the image.","Removing a person digitally.","Adding a new building digitally.","Combining several invented objects into the scene."],"answer":0,"evidence":"Basic cropping and exposure correction are allowed.","explain":"Cropping is allowed; adding or removing scene elements is not.","skill":"Detail"},{"q":"What happens to copyright in submitted images?","options":["The photographers retain it.","It is permanently transferred to the judges.","It is sold automatically to advertisers.","It is cancelled when an entry wins."],"answer":0,"evidence":"Entrants retain copyright","explain":"Display permission does not transfer ownership.","skill":"Detail"},{"q":"What will finalists be asked to supply?","options":["The original unedited files.","A payment for exhibition space.","Three printed copies only.","Photographs from a previous calendar year."],"answer":0,"evidence":"asked to provide the original unedited files","explain":"Finalists must supply originals.","skill":"Detail"},{"q":"What is included among the judging criteria?","options":["How clearly an image tells a story.","The price of the camera used.","The number of digitally added objects.","The photographer's previous advertising contracts."],"answer":0,"evidence":"the clarity of the story conveyed","explain":"Narrative clarity is one of the listed criteria.","skill":"Detail"}]},{"id":"office-lease","title":"Office viewing appointment","text":"PROPERTY LISTING\n\nSuite 402, Alder House\nFloor area: 85 square metres\nAvailable from 1 September\nMonthly rent includes heating and building maintenance. Electricity and internet are charged separately. The suite has a small meeting room and two reserved bicycle spaces. Car parking is not included.\n\nEMAIL FROM AGENT\n\nThank you for your interest in Suite 402. The current tenant is still occupying the space, so viewings require at least twenty-four hours' notice. I can offer Tuesday at 11 a.m. or Thursday at 3 p.m. Please reply with your preferred time and the number of visitors. We ask visitors not to photograph the tenant's documents or computer screens. A floor plan can be provided after the viewing.","questions":[{"q":"Which cost is included in the monthly rent?","options":["Heating","Internet","Electricity","Car parking"],"answer":0,"evidence":"Monthly rent includes heating and building maintenance.","explain":"Heating and maintenance are included; the other listed costs are not.","skill":"Detail"},{"q":"What parking provision is stated?","options":["Two reserved bicycle spaces.","Two reserved car spaces.","Unlimited visitor car parking.","A private loading area for trucks."],"answer":0,"evidence":"two reserved bicycle spaces. Car parking is not included.","explain":"The listing provides bicycle spaces, not car parking.","skill":"Detail"},{"q":"Why is advance notice required for viewings?","options":["The current tenant still uses the office.","The building is open only once a month.","The suite has no meeting room.","The agent lives in another country."],"answer":0,"evidence":"The current tenant is still occupying the space","explain":"Ongoing occupancy explains the notice requirement.","skill":"Detail"},{"q":"What information should a prospective visitor provide?","options":["A preferred time and the number of visitors.","The current tenant's computer password.","An electricity meter reading.","Payment for a full year of internet service."],"answer":0,"evidence":"your preferred time and the number of visitors","explain":"These are the two details requested for arranging the viewing.","skill":"Detail"},{"q":"What can be obtained after the viewing?","options":["A floor plan.","The tenant's confidential documents.","Guaranteed free electricity.","Ownership of the entire building."],"answer":0,"evidence":"A floor plan can be provided after the viewing.","explain":"A plan is offered after the appointment.","skill":"Detail"}]},{"id":"product-recall","title":"Travel mug safety notice","text":"PRODUCT SAFETY NOTICE — RIDGEWAY TRAVEL MUGS\n\nA manufacturing fault has been identified in the lids of 450-millilitre Ridgeway travel mugs bearing batch code R17. Under pressure, the lid may loosen and allow hot liquid to spill. Stop using affected mugs immediately.\n\nThe batch code is printed on the underside of the mug. Mugs marked R16 or R18 are not included in this notice. Customers with an R17 mug can request a replacement lid free of charge by completing the form on our service website. Upload a photograph showing the batch code; a purchase receipt is not required.\n\nKeep the mug body, but dispose of the faulty lid after the replacement arrives. Please do not return the whole mug to a shop. Replacement lids are expected to arrive within ten working days of a completed request.","questions":[{"q":"Which mugs are affected?","options":["450-millilitre mugs marked R17.","Every Ridgeway product ever sold.","Mugs marked R16 only.","Mugs marked R18 only."],"answer":0,"evidence":"450-millilitre Ridgeway travel mugs bearing batch code R17","explain":"The notice identifies a specific size and batch.","skill":"Detail"},{"q":"What should affected customers do immediately?","options":["Stop using the mugs.","Continue using them with hotter drinks.","Remove the printed batch code.","Return every mug in their kitchen."],"answer":0,"evidence":"Stop using affected mugs immediately.","explain":"The immediate safety instruction is to stop use.","skill":"Detail"},{"q":"What evidence is needed for a replacement request?","options":["A photograph of the batch code.","An original purchase receipt.","A video of liquid spilling.","A written statement from a retailer."],"answer":0,"evidence":"Upload a photograph showing the batch code; a purchase receipt is not required.","explain":"A code photograph is required, but a receipt is not.","skill":"Detail"},{"q":"What will be replaced?","options":["The lid only.","The entire mug and all accessories.","Only the printed label.","Any unrelated item from the same shop."],"answer":0,"evidence":"request a replacement lid free of charge","explain":"The free replacement is a lid.","skill":"Detail"},{"q":"What should customers do with the mug body?","options":["Keep it.","Dispose of it immediately.","Mail it to the manufacturer before applying.","Sell it with the faulty lid attached."],"answer":0,"evidence":"Keep the mug body","explain":"The notice distinguishes the reusable body from the faulty lid.","skill":"Detail"}]},{"id":"research-survey","title":"Workspace survey invitation","text":"From: Workplace Research Group\nSubject: Voluntary workspace survey\n\nWe are inviting staff who have used the new shared work area for at least one month to complete a short survey. It takes about eight minutes and asks about noise, lighting and access to meeting spaces. Responses will be collected until 17 June.\n\nThe survey does not ask for your name. Results will be reported only for groups of at least ten respondents so that individual answers are harder to identify. Managers will receive a summary, not the original response forms.\n\nParticipation is voluntary and will not affect workspace allocation. Please base your answers on your own recent experience rather than on comments from colleagues. Those who need an accessible version can contact the research group; requesting that version does not require disclosing survey answers.","questions":[{"q":"Who is invited to complete the survey?","options":["Staff with at least one month of experience in the shared area.","All visitors who passed through the building once.","Only managers who allocated desks.","People who have never used the work area."],"answer":0,"evidence":"staff who have used the new shared work area for at least one month","explain":"The invitation has a minimum-use requirement.","skill":"Detail"},{"q":"How long is the survey expected to take?","options":["About eight minutes.","At least one month.","Exactly ten hours.","Until the end of the year."],"answer":0,"evidence":"It takes about eight minutes","explain":"Eight minutes is the estimated completion time.","skill":"Detail"},{"q":"Why are results reported only for groups of ten or more?","options":["To make individual responses harder to identify.","To require every team to share identical answers.","To reduce the number of available desks.","To let managers see original response forms."],"answer":0,"evidence":"so that individual answers are harder to identify","explain":"The grouping rule protects response privacy.","skill":"Detail"},{"q":"What will managers receive?","options":["A summary of results.","Every original response form.","A list of named respondents.","Automatic changes to workspace allocations."],"answer":0,"evidence":"Managers will receive a summary, not the original response forms.","explain":"Managers get a summary rather than raw individual forms.","skill":"Detail"},{"q":"What should respondents use as the basis of their answers?","options":["Their own recent experience.","Only comments from colleagues.","The opinions they think managers prefer.","Reports about offices they have never visited."],"answer":0,"evidence":"your own recent experience rather than on comments from colleagues","explain":"The instructions ask for first-hand recent experience.","skill":"Detail"}]}]};
  const normalize=s=>String(s||'').normalize('NFKC').toLowerCase().replace(/[’‘]/g,"'").replace(/\s+/g,' ').trim();
  const E=()=>{if(!root.ToeicRandomEngine)throw new Error('抽題引擎未載入，請完成程式更新。');return root.ToeicRandomEngine;};
  const copy=x=>JSON.parse(JSON.stringify(x));
  const bank={6:[],7:[]};
  function signature(q){return normalize([q.stimulus,q.q,...q.options.map(normalize).sort()].join('\n'));}
  function validate(part,questions){
    const issues=[];
    if(!Array.isArray(questions)||!questions.length)return ['沒有題目'];
    if(part===6&&questions.length!==4)issues.push('Part 6 必須是一篇四格四題');
    if(part===7&&questions.length>5)issues.push('Part 7 題組超出本題庫規格');
    const ids=new Set(),content=new Set();
    for(const q of questions){
      if(q.part!==part)issues.push('題型不符');
      if(!q.id||ids.has(q.id))issues.push('題目識別重複');ids.add(q.id);
      const fp=signature(q);if(content.has(fp))issues.push('題目內容重複');content.add(fp);
      if(!q.stimulus||!q.q||!Array.isArray(q.options)||q.options.length!==4)issues.push('文章或選項格式錯誤');
      if(!Number.isInteger(q.answer)||q.answer<0||q.answer>=4)issues.push('正解位置錯誤');
      if(new Set((q.options||[]).map(normalize)).size!==4)issues.push('選項內容重複');
      if(part===6){
        const gaps=[...String(q.stimulus).matchAll(/\[([1-4])\] _____/g)].map(m=>Number(m[1]));
        if(gaps.join(',')!=='1,2,3,4'||!gaps.includes(q.gapNumber)||q.q!==`Which option best completes blank [${q.gapNumber}]?`)issues.push('Part 6 空格編號或題幹不符');
        if(!q.completedText?.includes(q.options[q.answer]))issues.push('填空正解未對應完整文章');
      }else if(!q.evidence||!q.stimulus.includes(q.evidence))issues.push('閱讀證據不在文章內');
    }
    if(new Set(questions.map(q=>q.contextFingerprint)).size!==1)issues.push('同題組混入不同文章');
    if(part===6&&questions.map(q=>q.gapNumber).join(',')!=='1,2,3,4')issues.push('Part 6 四格順序錯誤');
    return [...new Set(issues)];
  }
  for(const part of [6,7]){
    const sources=DATA[part===6?'part6':'part7'];
    const seen=new Set();
    for(const raw of sources){
      const text=raw.text.replace(/\{\{([1-4])\}\}/g,(_,n)=>`[${n}] _____`);
      // Identity is derived from full content, not a timestamp, topic label or option order.
      const contextFingerprint=normalize(text);
      if(seen.has(contextFingerprint))throw new Error('題庫包含重複文章');seen.add(contextFingerprint);
      const contextId=`p${part}-${raw.id}`;
      const complete=part===6?raw.text.replace(/\{\{([1-4])\}\}/g,(_,n)=>raw.gaps[Number(n)-1].options[raw.gaps[Number(n)-1].answer]):null;
      const questions=(part===6?raw.gaps:raw.questions).map((item,i)=>{
        const out={...copy(item),id:`${contextId}-q${i+1}`,canonicalId:`${contextId}-q${i+1}`,part,contextId,contextFingerprint,contentVersion:VERSION,contextTitle:raw.title,stimulus:text};
        if(part===6)Object.assign(out,{q:`Which option best completes blank [${i+1}]?`,gapNumber:i+1,completedText:complete});
        out.contentFingerprint=signature(out);
        return out;
      });
      const issues=validate(part,questions);if(issues.length)throw new Error(contextId+': '+issues.join('; '));
      bank[part].push({id:contextId,title:raw.title,contextFingerprint,questions});
    }
  }
  function readState(){
    let raw;
    try{raw=root.localStorage?.getItem(STORAGE_KEY);}catch{throw new Error('無法讀取抽題紀錄；尚未產生新題組。');}
    if(!raw)return {schema:1,serial:0,seen:{},reservations:[]};
    let state;try{state=JSON.parse(raw);}catch{throw new Error('抽題索引格式損壞，已停止且未覆寫任何紀錄。');}
    if(!state||state.schema!==1||!Number.isSafeInteger(state.serial)||state.serial<0||!state.seen||typeof state.seen!=='object'||Array.isArray(state.seen)||!Array.isArray(state.reservations))throw new Error('抽題索引不相容，已停止且保留原資料。');
    for(const v of Object.values(state.seen))if(!v||!Number.isSafeInteger(v.serial)||v.serial<1||!Number.isSafeInteger(v.draws)||v.draws<1)throw new Error('抽題索引內容損壞，已停止且保留原資料。');
    return state;
  }
  function draw(part,count,session,block=0,excluded=[]){
    if(!bank[part]||!Number.isInteger(count)||count<1||count>(part===6?4:5)||(part===6&&count!==4))throw new RangeError('不支援的閱讀題組題數');
    if(!Array.isArray(excluded))throw new TypeError('Invalid context exclusions');
    const engine=E(),state=readState(),key=JSON.stringify([VERSION,part,count,String(session),block]);
    const old=state.reservations.find(x=>x.key===key);
    const blocked=new Set(excluded);
    let chosen,repeat;
    if(old){
      chosen=bank[part].find(x=>x.id===old.id&&x.contextFingerprint===old.fingerprint);
      if(!chosen)throw new Error('本次保留題組不符新版題庫，原紀錄未覆寫。');
      if(blocked.has(chosen.contextFingerprint)||blocked.has(chosen.id))throw new Error('同一次練習已使用此文章，已阻止重複出題。');
      repeat=old.repeat;
    }else{
      const available=bank[part].filter(x=>!blocked.has(x.contextFingerprint)&&!blocked.has(x.id));
      if(!available.length)throw new Error('本次已用完此 Part 的不同題組，請完成本次練習後再開始。');
      const min=Math.min(...available.map(x=>state.seen[x.contextFingerprint]?.serial||0));
      const pool=available.filter(x=>(state.seen[x.contextFingerprint]?.serial||0)===min);
      chosen=engine.shuffle(pool,engine.rng(key+'|'+engine.nonce()))[0];
      const prior=state.seen[chosen.contextFingerprint];repeat=Boolean(prior);
      state.serial++;state.seen[chosen.contextFingerprint]={serial:state.serial,draws:(prior?.draws||0)+1};
      state.reservations.push({key,id:chosen.id,fingerprint:chosen.contextFingerprint,repeat});
      // This bounded list contains only draw reservations, never learning/goal records.
      state.reservations=state.reservations.slice(-256);
      try{
        if(!root.localStorage)throw new Error('No storage');
        root.localStorage.setItem(STORAGE_KEY,JSON.stringify(state));
      }catch{throw new Error('抽題紀錄無法儲存，已停止出題以免重複；請先匯出學習備份並檢查裝置儲存空間。');}
    }
    const indices=part===6?[0,1,2,3]:engine.sampleIndices(5,count,key).sort((a,b)=>a-b);
    const questions=indices.map(i=>copy(chosen.questions[i]));
    const seenCount=bank[part].filter(x=>state.seen[x.contextFingerprint]).length;
    return {title:chosen.title,questions,contextId:chosen.id,novelty:{repeat,total:bank[part].length,seen:seenCount,version:VERSION}};
  }
  function previewQuestion(part,index,seed){
    if(!bank[part])throw new RangeError('Unsupported part');
    const n=part===6?4:5,which=(E().hashSeed(String(seed))+Math.floor(index/n))%bank[part].length;
    return copy(bank[part][which].questions[((index%n)+n)%n]);
  }
  function stats(){return Object.fromEntries([6,7].map(p=>[p,{contexts:bank[p].length,questions:bank[p].reduce((n,s)=>n+s.questions.length,0)}]));}
  root.ToeicReadingBank={VERSION,STORAGE_KEY,draw,validate,previewQuestion,stats,inspect:()=>copy(bank),signature};
  if(typeof module!=='undefined'&&module.exports)module.exports=root.ToeicReadingBank;
})(typeof window!=='undefined'?window:globalThis);
